import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-final111-20261019';const ids=JSON.parse(await fs.readFile(dir+'/job-ids.json'));const jobs=await db('sequence_jobs',{id:'in.('+ids.map(j=>j.id).join(',')+')',select:'id,contact_id,status,provider_sid,error,last_error,sent_at',limit:'200'});const pids=jobs.map(j=>String(j.provider_sid||'').replace('telnyx:','')).filter(Boolean);let events=[];for(let i=0;i<pids.length;i+=80)events.push(...await db('crm_sms_provider_events',{provider_message_id:'in.('+pids.slice(i,i+80).join(',')+')',event_type:'eq.message.finalized',select:'provider_message_id,status,occurred_at',order:'occurred_at.asc',limit:'1000'}));const last=new Map(events.map(e=>[e.provider_message_id,e]));const counts={};for(const j of jobs){const k=last.get(String(j.provider_sid||'').replace('telnyx:',''))?.status||(j.provider_sid?'awaiting_receipt':j.status);counts[k]=(counts[k]||0)+1;}const summary={at:new Date().toISOString(),total:jobs.length,provider_accepted:pids.length,counts,technical_holds:jobs.filter(j=>j.status==='failed'&&!j.provider_sid)};await fs.writeFile(dir+'/live-status.json',JSON.stringify({summary,jobs,events},null,2));console.log(JSON.stringify(summary));
